```js
function debounceLatest(fn, ms) {
  let timer = null;

  const wrapper = function (...args) {
    // clear any pending call
    if (timer) clearTimeout(timer);

    // schedule the latest call
    timer = setTimeout(() => {
      timer = null;           // clean up
      fn(...args);
    }, ms);
  };

  // expose a cancel method
  wrapper.cancel = () => {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };

  return wrapper;
}
```

