```javascript
function evaluateRPN(tokens) {
  if (!Array.isArray(tokens) || tokens.length === 0) {
    throw new Error("Invalid expression: empty input");
  }

  const stack = [];

  const isOperator = (t) => ["+", "-", "*", "/"].includes(t);
  const toInt = (t) => {
    const n = Number(t);
    if (!Number.isInteger(n)) throw new Error(`Invalid token: ${t}`);
    return n;
  };

  for (const token of tokens) {
    if (isOperator(token)) {
      if (stack.length < 2) {
        throw new Error("Invalid expression: operator without enough operands");
      }
      const b = stack.pop();
      const a = stack.pop();
      let result;
      switch (token) {
        case "+":
          result = a + b;
          break;
        case "-":
          result = a - b;
          break;
        case "*":
          result = a * b;
          break;
        case "/":
          if (b === 0) {
            throw new Error("Division by zero");
          }
          // Truncate toward zero
          result = a / b > 0 ? Math.floor(a / b) : Math.ceil(a / b);
          break;
      }
      stack.push(result);
    } else {
      // token should be a valid integer (may be negative)
      stack.push(toInt(token));
    }
  }

  if (stack.length !== 1) {
    throw new Error("Invalid expression: leftover operands");
  }

  return stack[0];
}
```

Here is the function to parse the duration string into seconds.

```javascript
function parseDuration(text) {
  if (typeof text !== 'string' || !text) return null;
  const match = text.match(/^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/i);
  if (!match) return null;
  const [, h, m, s] = match;
  if (h === undefined && m === undefined && s === undefined) return null;
  return (h ? Number(h) * 3600 : 0) + (m ? Number(m) * 60 : 0) + (s ? Number(s) : 0);
}
```

It enforces hours, minutes, and seconds in exact sequence, handles uppercase letters, rejects decimals, spaces, or stray numbers, and requires at least one unit to be present.

